// Classic keeps the card above a button bar. Overlay and CardOnly fill the screen with the card and
// float the controls over its art; CardOnly hides them again a few seconds after the last touch.
enum class Layout : uint8_t { Classic, Overlay, CardOnly };
constexpr uint8_t LAYOUT_COUNT = 3;
const char *const LAYOUT_LABELS[LAYOUT_COUNT] = {"CLASSIC", "OVERLAY", "CARD ONLY"};

// The TN panel washes light colors out when seen from an angle, as when the board lies on a table:
// whites blow out and the art turns pale. Each tone level darkens the card a little more: a gamma
// curve pulls the midtones down and a gain below 1 lowers the white point. It applies to the art, the
// frame and the plates of the card, but not to the rest of the interface. Level 0 leaves it all as is.
constexpr uint8_t TONE_LEVELS = 6;
constexpr float TONE_GAMMA_STEP = 0.2f;
constexpr float TONE_GAIN_STEP = 0.04f;

struct Config {
  uint8_t brightness;  // 1..BRIGHTNESS_LEVELS
  uint8_t timeout;     // Index into TIMEOUT_SECONDS.
  uint8_t layout;      // A Layout value.
  uint8_t tone;        // 0..TONE_LEVELS - 1
  uint8_t flipped;     // 1 turns the whole screen upside down.
  uint8_t gammaMode;   // Index into GAMMA_PROFILES.
};
// Earlier firmware saved fewer fields; the others then keep their defaults.
constexpr size_t CONFIG_V1_SIZE = offsetof(Config, tone);
constexpr size_t CONFIG_V2_SIZE = offsetof(Config, gammaMode);
constexpr Config DEFAULT_CONFIG = {BRIGHTNESS_LEVELS, TIMEOUT_COUNT - 1, static_cast<uint8_t>(Layout::Classic), 0, 0, 0};

// This board's panel needs its colors inverted, and right after the controller's own init its gamma is
// off: the image looks washed out and the lights blow out. Selecting another gamma curve and then the
// usual one again, once the display is on, corrects it (TFT_eSPI issue 2985). The profiles are what that
// step programs; the settings can switch between them for a panel that still looks wrong.
constexpr uint8_t REG_GAMMASET = 0x26;
constexpr uint8_t REG_DFUNCTR = 0xB6;
constexpr uint8_t REG_GAMMA_POS = 0xE0;
constexpr uint8_t REG_GAMMA_NEG = 0xE1;
constexpr uint8_t GAMMA_CURVE = 0x01;        // The curve the controller's init selects.
constexpr uint8_t GAMMA_CURVE_OTHER = 0x02;  // Any other curve will do to reselect the first.
constexpr uint32_t GAMMA_SETTLE_MS = 120;

// The gamma tables of the controller's init, and the ones TFT_eSPI gives ST7789 panels.
const uint8_t GAMMA_VENDOR_POS[] = {0x0F, 0x2A, 0x28, 0x08, 0x0E, 0x08, 0x54, 0xA9, 0x43, 0x0A, 0x0F, 0x00, 0x00, 0x00, 0x00};
const uint8_t GAMMA_VENDOR_NEG[] = {0x00, 0x15, 0x17, 0x07, 0x11, 0x06, 0x2B, 0x56, 0x3C, 0x05, 0x10, 0x0F, 0x3F, 0x3F, 0x0F};
const uint8_t GAMMA_ST7789_POS[] = {0xD0, 0x00, 0x02, 0x07, 0x0A, 0x28, 0x32, 0x44, 0x42, 0x06, 0x0E, 0x12, 0x14, 0x17};
const uint8_t GAMMA_ST7789_NEG[] = {0xD0, 0x00, 0x02, 0x07, 0x0A, 0x28, 0x31, 0x54, 0x47, 0x0E, 0x1C, 0x17, 0x1B, 0x1E};

struct GammaProfile {
  const char *label;
  const uint8_t *positive;  // Tables for the two polarities the panel is driven with.
  const uint8_t *negative;
  uint8_t length;
  bool normallyBlack;  // Tells the controller the glass is normally black, instead of inverting the image.
};

const GammaProfile GAMMA_PROFILES[] = {
    {"RECOMMENDED", GAMMA_VENDOR_POS, GAMMA_VENDOR_NEG, sizeof(GAMMA_VENDOR_POS), false},
    {"NO INVERSION", GAMMA_VENDOR_POS, GAMMA_VENDOR_NEG, sizeof(GAMMA_VENDOR_POS), true},
    {"ST7789 GAMMA", GAMMA_ST7789_POS, GAMMA_ST7789_NEG, sizeof(GAMMA_ST7789_POS), false},
};
constexpr uint8_t GAMMA_COUNT = sizeof(GAMMA_PROFILES) / sizeof(GAMMA_PROFILES[0]);

